+    /// Verify the QE Identity signature against the issuer chain.
+    /// This ensures the QE Identity is authentic and issued by Intel.
+    pub fn verify(&self) -> Result<()> {
+        let qe_cert = parse_qe_identity(&self.qe_identity)?;
+        let sig = parse_ecdsa_signature(&self.qe_identity_signature)?;
+
+        let chain = parse_x509_chain(&self.qe_identity_issuer_chain)?;
+        if chain.is_empty() {
+            return Err(Error::InvalidCollateral);
+        }
+
+        // Verify QE identity signed by first issuer
+        chain[0].public_key()?.verify(&sig, &qe_cert.tbs_asn1()?)?;
+
+        // Verify issuer chain up to root
+        for i in 1..chain.len() {
+            chain[i].public_key()?.verify(&chain[i-1].signature()?, &chain[i-1].tbs_asn1()?)?;
+        }
+
+        // Enforce policy: root must be Intel Production CA, check versions/extensions
+        enforce_qe_policy(&qe_cert, &chain)?;
+
+        Ok(())
+    }
+}

